inline constexpr int numPresets = 3000;
inline triad::mod::Shape shape (int index)
{
    const auto& e = entries[juce::jlimit (0, numPresets - 1, index)];
    triad::mod::Shape s;
    for (int i = 0; i < e.count; ++i) s.push_back ({ points[e.first + i].x, points[e.first + i].y, points[e.first + i].curve });
    return s;
}
inline std::vector<int> presetsIn (int folder)
{
    std::vector<int> list;
    for (int i = 0; i < numPresets; ++i) if (entries[i].folder == folder) list.push_back (i);
    return list;
}
